int add_route_to_fib6(struct fib6_node *root, struct rt6_info *rt, struct nl_info *info) {
    int err = 0;
    struct fib6_node *subtree = NULL;

    if (!(info->nlflags & (RTM_F_CREATE | RTM_F_REPLACE))) {
        return -EINVAL;
    }

    err = fib6_add_1(root, rt, info);
    if (err < 0) {
        return err;
    }

    if (rt->rt6i_src) {
        subtree = fib6_node_create();
        if (!subtree) {
            return -ENOMEM;
        }

        err = fib6_add_1(subtree, rt, info);
        if (err < 0) {
            fib6_node_free(subtree);
            return err;
        }
    }

    if (err == 0) {
        rt6_info_hold(rt);
    } else {
        rt6_info_release(rt);
    }

    return err;
}

int add_route_to_fib6(struct fib6_node *root, struct rt6_info *rt, struct nl_info *info) {
    int err;

    if ((info->nl_net->commit.count++ == 0) && (info->nl_net->commit.cnt == 0))
        info->nl_net->commit.root = root;

    if (info->nl_net->commit.cnt > 0) {
        info->nl_net->commit.cnt--;
        err = fib6_add_1(root, rt, info);
        if (err < 0)
            info->nl_net->commit.cnt++;
        goto out;
    }

    err = fib6_add_1(root, rt, info);
    if (err < 0)
        goto out;

    if (rt->rt6i_src) {
        struct fib6_node *subroot;

        subroot = fib6_node_alloc();
        if (!subroot) {
            err = -ENOMEM;
            goto out;
        }

        subroot->parent = root;
        root->child = subroot;

        err = fib6_add_1(subroot, rt, info);
        if (err < 0) {
            fib6_node_free(subroot);
            root->child = NULL;
            goto out;
        }
    }

out:
