int add_ipv6_route(struct fib6_node *root, struct rt6_info *rt, struct nl_info *info) {
    int err;

    if (info->nlflags & RTM_F_CREATE) {
        err = fib6_add_1(root, rt, info);
        if (err < 0)
            return err;
    } else {
        return -EINVAL;
    }

    if (rt->rt6i_src) {
        struct fib6_node *subtree;

        subtree = fib6_node_create_subtree(root);
        if (!subtree) {
            fib6_free_route(rt);
            return -ENOMEM;
        }

        rt->rt6i_node = subtree;
        fib6_add_source_route(subtree, rt);
    }

    rt6_update_expires(rt, info->lifetime);

    return 0;
}

int add_route_to_fib6(struct fib6_node *root, struct rt6_info *rt, struct nl_info *info) {
    int err;

    if ((info->nl_net->event & RTM_NEWDST) && !(info->nl_net->flags & RTM_F_CREATE)) {
        return -EINVAL;
    }

    err = fib6_add_1(root, rt, info);
    if (err < 0)
        return err;

    if (rt->rt6i_src) {
        struct fib6_node *subtree = fib6_find_child(root, rt->rt6i_src);
        if (!subtree) {
            subtree = fib6_node_alloc();
            if (!subtree)
                return -ENOMEM;

            if (fib6_insert_child(root, subtree) < 0) {
                kfree(subtree);
                return -ENOMEM;
            }
        }

        err = fib6_add_1(subtree, rt, info);
        if (err < 0) {
            fib6_repair_tree(subtree);
            return err;
        }
    }

    rt6_hold(rt);
    return 0;
}
